def analyze(d):
    effects=[]
    for s in sorted(set(r["site"] for r in d["rows"])):
        a=[r["y"] for r in d["rows"] if r["site"]==s and r["arm"]==1]
        b=[r["y"] for r in d["rows"] if r["site"]==s and r["arm"]==0]
        effects.append(sum(a)/len(a)-sum(b)/len(b))
    return sum(effects)/len(effects)

