def analyze(d):
    queue=[(0,0)]
    seen={0}
    while queue:
        node,cost=queue.pop(0)
        if node==d["n"]-1: return cost
        for a,b,w in d["edges"]:
            if a==node and b not in seen:
                seen.add(b)
                queue.append((b,cost+w))

def analyze(d):
    dist=[1e30]*d["n"]
    dist[0]=0
    for _ in range(d["n"]-1):
        for a,b,w in d["edges"]:
            dist[b]=min(dist[b],dist[a]+w)
    return dist[-1]

def analyze(d):
    out=[]
    for t in d["texts"]:
        words=t.split()
        v=1 if words[-1] in ["good","great"] else -1
        for w in reversed(words[:-1]):
            if w!="not": break
            v=-v
        out.append(v)
    return out
